// Conformance: the TypeScript decision layer must reproduce the Python reference exactly.
//
// The fixtures in ../fixtures/decision-layer-golden.json are generated by
// tools/gen_decision_layer_fixtures.py driving the REAL crossage_fr.match code. If this test
// passes, the port is faithful; if the Python reference changes, regenerate and this catches drift.
//
// Run: npx tsx --test test/conformance.test.ts   (from the package dir)

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import {
  PlattCalibrator,
  fuseScores,
  asNormScore,
  CohortNormalizer,
  normalizedPairCenter,
  AdaptiveLinearCalibrator,
  computeAgeGap,
  confidenceForGap,
  reviewThresholdForGap,
  bandForScore,
  thresholdsForPose,
  l2normalize,
} from '../src/index';
import type { Thresholds } from '../src/index';

const __dirname = dirname(fileURLToPath(import.meta.url));
const golden = JSON.parse(
  readFileSync(join(__dirname, '..', 'fixtures', 'decision-layer-golden.json'), 'utf8'),
);

// Float64 arithmetic in both runtimes should agree to well within this.
const EPS = 1e-9;

function closeTo(actual: number, expected: number, label: string): void {
  assert.ok(
    Math.abs(actual - expected) <= EPS + EPS * Math.abs(expected),
    `${label}: got ${actual}, expected ${expected} (|d|=${Math.abs(actual - expected)})`,
  );
}

function closeArray(actual: number[], expected: number[], label: string): void {
  assert.equal(actual.length, expected.length, `${label}: length ${actual.length} != ${expected.length}`);
  for (let i = 0; i < expected.length; i++) closeTo(actual[i], expected[i], `${label}[${i}]`);
}

function toThresholds(t: Record<string, number>): Thresholds {
  return { confident: t.confident, likely: t.likely, relaxedChild: t.relaxed_child, qualityMin: t.quality_min };
}

test('Platt probability', () => {
  for (const c of golden.platt) {
    closeTo(new PlattCalibrator(c.a, c.b).probability(c.score), c.out, `platt(a=${c.a},b=${c.b},s=${c.score})`);
  }
});

test('fuseScores', () => {
  for (const c of golden.fuse) {
    closeTo(fuseScores(c.scores, c.weights), c.out, `fuse(${JSON.stringify(c.scores)})`);
  }
});

test('asNormScore', () => {
  for (const c of golden.asNorm) {
    closeTo(asNormScore(c.raw, c.cohort, c.topK), c.out, `asNorm(raw=${c.raw},k=${c.topK})`);
  }
});

test('l2normalize', () => {
  for (const c of golden.l2normalize) {
    closeArray(l2normalize(c.vector), c.out, 'l2normalize');
  }
});

test('CohortNormalizer.scores/normalize/normalizePair', () => {
  for (const c of golden.cohortNormalizer) {
    const norm = new CohortNormalizer(c.cohort);
    closeArray(norm.scores(c.probe), c.scores, 'cohort.scores');
    closeTo(norm.normalize(c.probe, c.raw, c.topK), c.normalize, 'cohort.normalize');
    closeTo(norm.normalizePair(c.probe, c.reference, c.raw, c.pairTopK), c.normalizePair, 'cohort.normalizePair');
  }
});

test('normalizedPairCenter', () => {
  for (const c of golden.pairCenter) {
    const out = normalizedPairCenter(c.left, c.right);
    if (c.out === null) {
      assert.equal(out, null, 'pairCenter should be null');
    } else {
      assert.ok(out !== null, 'pairCenter should not be null');
      closeArray(out as number[], c.out, 'pairCenter');
    }
  }
});

test('AdaptiveLinearCalibrator.fromPayload + probability', () => {
  for (const c of golden.adaptive) {
    const calib = AdaptiveLinearCalibrator.fromPayload(c.payload);
    closeTo(calib.probability(c.center, c.raw), c.out, 'adaptive.probability');
  }
});

test('computeAgeGap', () => {
  for (const c of golden.ageGap) {
    const r = computeAgeGap(c.candidateDate, c.referenceDate, c.candidateProvenance, c.referenceProvenance);
    if (c.years === null) assert.equal(r.years, null, 'ageGap.years');
    else closeTo(r.years as number, c.years, 'ageGap.years');
    assert.equal(r.confidence, c.confidence, `ageGap.confidence for ${c.candidateDate}/${c.referenceDate}`);
    assert.equal(r.flag, c.flag, 'ageGap.flag');
  }
});

test('confidenceForGap', () => {
  for (const c of golden.confidenceForGap) {
    assert.equal(confidenceForGap(c.years), c.out, `confidenceForGap(${c.years})`);
  }
});

test('reviewThresholdForGap', () => {
  for (const c of golden.reviewThreshold) {
    closeTo(reviewThresholdForGap(c.base, c.years, c.confidence), c.out, 'reviewThreshold');
  }
});

test('bandForScore', () => {
  for (const c of golden.bandForScore) {
    assert.equal(bandForScore(c.score, toThresholds(c.thresholds)), c.out, `bandForScore(${c.score})`);
  }
});

test('thresholdsForPose', () => {
  for (const c of golden.thresholdsForPose) {
    const out = thresholdsForPose(toThresholds(c.thresholds), c.pose);
    closeTo(out.confident, c.out.confident, `pose ${c.pose} confident`);
    closeTo(out.likely, c.out.likely, `pose ${c.pose} likely`);
    closeTo(out.relaxedChild, c.out.relaxed_child, `pose ${c.pose} relaxedChild`);
    closeTo(out.qualityMin, c.out.quality_min, `pose ${c.pose} qualityMin`);
  }
});
